test("a call that is not a commit or a pull request keeps its command", async ($: Engine, on: On) => {
  const seen: string[] = [];
  engine(on, { seen });
  for (const command of [
    "git status",
    "git commit --dry-run -m x",
    'echo "git commit -m x"',
    "git log --grep commit",
  ])
    await bash($, command);
  expect(seen).toStrictEqual([
    "git status",
    "git commit --dry-run -m x",
    'echo "git commit -m x"',
    "git log --grep commit",
  ]);
});

